/**
 * SL-ANDROID-COMPATIBILITY-RELEASE-GATE-02 — keeps the production signing hook in the GENERATED android/ project.
 *
 * android/ is generated by `expo prebuild` and is not committed, so anything edited there by hand is lost on a clean
 * checkout. This config plugin re-applies the hook every time the native project is generated.
 *
 * Behaviour of the generated app/build.gradle:
 *   - default (no properties given): the release build is signed with the project's debug keystore, exactly as the
 *     published 1.0.0 - 1.0.2 APKs were, so an installed app can be updated in place;
 *   - when the four Gradle properties SL_RELEASE_STORE_FILE / _STORE_PASSWORD / _KEY_ALIAS / _KEY_PASSWORD are
 *     supplied (-P on the command line or ~/.gradle/gradle.properties), the release build uses that keystore.
 * No passwords or keystores are stored in the repository.
 */
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// SL release signing hook';

const SIGNING_BLOCK = `
        ${MARKER}
        if (findProperty('SL_RELEASE_STORE_FILE')) {
            release {
                storeFile file(findProperty('SL_RELEASE_STORE_FILE'))
                storePassword findProperty('SL_RELEASE_STORE_PASSWORD')
                keyAlias findProperty('SL_RELEASE_KEY_ALIAS')
                keyPassword findProperty('SL_RELEASE_KEY_PASSWORD')
            }
        }`;

function applyReleaseSigning(contents) {
  if (contents.includes(MARKER)) return contents; // already applied (idempotent)

  // 1. add the optional production signing config after the debug one
  const debugBlock = /(signingConfigs\s*\{\s*debug\s*\{[^}]*\})/;
  if (!debugBlock.test(contents)) throw new Error('withReleaseSigning: could not find signingConfigs.debug in app/build.gradle');
  let out = contents.replace(debugBlock, `$1${SIGNING_BLOCK}`);

  // 2. choose it for the release build type only when it is configured
  const releaseSigning = /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig signingConfigs\.debug/;
  if (!releaseSigning.test(out)) throw new Error('withReleaseSigning: could not find the release signingConfig in app/build.gradle');
  out = out.replace(releaseSigning, `$1signingConfig findProperty('SL_RELEASE_STORE_FILE') ? signingConfigs.release : signingConfigs.debug`);
  return out;
}

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    cfg.modResults.contents = applyReleaseSigning(cfg.modResults.contents);
    return cfg;
  });
};
module.exports.applyReleaseSigning = applyReleaseSigning;
